mapper.select:
SELECT b.auth_group_id, b.auth_group_name, a.auth_id, a.auth_name FROM CMS_AUTH a, CMS_AUTH_GROUP b WHERE a.auth_group_id = b.auth_group_id
AND a.auth_group_id = #{auth_group_id}
AND a.use_yn = 'y' AND to_number(a.auth_id) > 200 ORDER BY b.auth_group_id, a.auth_id
